import pandas as pd

def generate_the_invoice(products: pd.DataFrame, purchases: pd.DataFrame) -> pd.DataFrame:
    df = purchases.merge(products, on='product_id')
    df['item_cost'] = df['quantity'] * df['price']
    totals = df.groupby('invoice_id')['item_cost'].sum().reset_index()
    totals = totals.sort_values(by=['item_cost', 'invoice_id'], ascending=[False, True])
    if totals.empty:
        return pd.DataFrame(columns=['product_id', 'quantity', 'price'])
    top_invoice = totals.iloc[0]['invoice_id']
    res = df[df['invoice_id'] == top_invoice][['product_id', 'quantity', 'item_cost']]
    return res.rename(columns={'item_cost': 'price'})
